1	import { useMemo } from 'react';
2	import { createClient } from 'contentful';
3	import type { ContentfulClientApi } from 'contentful';
4	import { getContentfulConfig, CONTENTFUL_PREVIEW_HOST, CONTENTFUL_DELIVERY_HOST } from '../config/contentful';
5	
6	type UseContentfulClientOptions = {
7	  /** Request the Preview API (CPA) instead of the Delivery API (CDA). */
8	  preview?: boolean;
9	};
10	
11	type UseContentfulClientResult = {
12	  /**
13	   * Memoised Contentful client, or `null` when required config (space/token) is missing.
14	   * The SDK's client generic is intentionally loose here — the Experiences SDK
15	   * (`useFetchBySlug`/`useFetchById`) accepts a broadly-typed client, matching the page components.
16	   */
17	  client: ContentfulClientApi<any> | null;
18	  /**
19	   * `true` when preview was requested but no CPA token is configured — the non-prod gate.
20	   * Callers MUST fail explicitly (HTTP 404 + `<Seo noIndex />`); they must never fall back to delivery.
21	   */
22	  previewUnavailable: boolean;
23	  /** `true` when the client is actually in preview mode (preview requested AND a CPA token is present). */
24	  isPreview: boolean;
25	};
26	
27	/**
28	 * Builds a memoised Contentful Delivery/Preview client from environment config, centralising
29	 * the CPA-token gate so the `/preview` route and `?preview` Experience pages resolve the
30	 * preview-vs-delivery decision — and the "no token" behaviour — identically.
31	 *
32	 * @param options.preview whether to use the Preview API (CPA) host + token
33	 * @returns the memoised client (or `null` if unconfigured) plus preview-state flags for gating
34	 */
35	export const useContentfulClient = ({
36	  preview = false,
37	}: UseContentfulClientOptions = {}): UseContentfulClientResult => {
38	  const { spaceId, environment, previewAccessToken, accessToken } = getContentfulConfig() ?? {};
39	  const previewUnavailable = preview && !previewAccessToken;
40	  const isPreview = preview && !!previewAccessToken;
41	  const token = isPreview ? previewAccessToken : accessToken;
42	  const host = isPreview ? CONTENTFUL_PREVIEW_HOST : CONTENTFUL_DELIVERY_HOST;
43	
44	  const client = useMemo(() => {
45	    if (!spaceId || !token) return null;
46	    return createClient({ space: spaceId, environment, accessToken: token, host });
47	  }, [spaceId, environment, token, host]);
48	
49	  return { client, previewUnavailable, isPreview };
50	};
